// ClearNightSiriBridge.swift
// Injected into the main app target by plugins/withSiriIntents.js — do not
// edit ios/ClearNight directly, it's regenerated by `expo prebuild`.
//
// Two jobs:
// 1. ClearNightForecastCache — a plain Swift enum (no RN dependency) that
//    reads/writes a small JSON snapshot of every saved location's 6-night
//    forecast in the shared App Group container. The App Intents below read
//    from it directly. This has to be dependency-free because App Intents
//    can run before the RN/JS runtime is alive.
// 2. ClearNightSiriBridge — the thin RCTBridgeModule wrapper JS calls to
//    write that cache (on every forecast refresh) and to check for a
//    pending Siri-triggered navigation (on app foreground).

import Foundation
import React

private let kAppGroupID = "group.com.clearnight.app"
private let kCacheKey = "clearnight.siri.forecastCache.v1"
private let kPendingNavKey = "clearnight.siri.pendingNavigation.v1"

struct CachedNight: Codable {
    let day: String            // "Tonight", "Fri", "Sat", ...
    let date: String           // "Sep 20"
    let weekdayIndex: Int      // 0 = Sun ... 6 = Sat, in the location's own local time
    let verdict: String        // "excellent" | "good" | "fair" | "poor"
    let verdictWord: String    // "Pristine" | "Great" | "Workable" | "Washed out"
    let score: Int
    let windowLabel: String?   // e.g. "11:10pm – 4:20am", nil if no clear window
    let clearBy: String?
    let primeDark: String?
    let moonPhase: String
    let seeingWord: String
}

struct CachedLocation: Codable {
    let name: String
    let region: String
    let latitude: Double
    let longitude: Double
    let updatedAtMs: Double
    let nights: [CachedNight]
}

/// Shared-storage helper. Safe to call from any process (main app or an
/// App Intents extension) since it only touches the App Group container.
enum ClearNightForecastCache {
    static func write(json: String) {
        UserDefaults(suiteName: kAppGroupID)?.set(json, forKey: kCacheKey)
    }

    static func readAll() -> [CachedLocation] {
        guard let json = UserDefaults(suiteName: kAppGroupID)?.string(forKey: kCacheKey),
              let data = json.data(using: .utf8) else { return [] }
        return (try? JSONDecoder().decode([CachedLocation].self, from: data)) ?? []
    }

    /// Left for the RN app to pick up next time it becomes active, so a
    /// "this week" / "this weekend" Siri query opens straight to the spot
    /// that was asked about instead of wherever the app last was.
    static func setPendingNavigation(locationName: String) {
        let payload = ["locationName": locationName]
        if let data = try? JSONEncoder().encode(payload), let json = String(data: data, encoding: .utf8) {
            UserDefaults(suiteName: kAppGroupID)?.set(json, forKey: kPendingNavKey)
        }
    }

    static func readPendingNavigation() -> String? {
        UserDefaults(suiteName: kAppGroupID)?.string(forKey: kPendingNavKey)
    }

    static func clearPendingNavigation() {
        UserDefaults(suiteName: kAppGroupID)?.removeObject(forKey: kPendingNavKey)
    }
}

@objc(ClearNightSiriBridge)
class ClearNightSiriBridge: NSObject, RCTBridgeModule {
    static func moduleName() -> String! { "ClearNightSiriBridge" }
    static func requiresMainQueueSetup() -> Bool { false }

    @objc(writeForecastCache:resolver:rejecter:)
    func writeForecastCache(_ json: String, resolver resolve: @escaping RCTPromiseResolveBlock, rejecter reject: @escaping RCTPromiseRejectBlock) {
        ClearNightForecastCache.write(json: json)
        resolve(nil)
    }

    @objc(readPendingNavigation:rejecter:)
    func readPendingNavigation(_ resolve: @escaping RCTPromiseResolveBlock, rejecter reject: @escaping RCTPromiseRejectBlock) {
        resolve(ClearNightForecastCache.readPendingNavigation())
    }

    @objc(clearPendingNavigation:rejecter:)
    func clearPendingNavigation(_ resolve: @escaping RCTPromiseResolveBlock, rejecter reject: @escaping RCTPromiseRejectBlock) {
        ClearNightForecastCache.clearPendingNavigation()
        resolve(nil)
    }
}
